//! Phase 5a — SwapMath.computeSwapStep: reference cross-check, differential over
//! the full branch space, negative soundness, and prove+verify.
//!
//! 1. REFERENCE CROSS-CHECK: an independent v3 oracle (generated by a standalone
//!    Python port, scratchpad/v3_oracle.py) emits a static table of
//!    (current, target, liquidity, sign, magnitude, feePips) -> (next, in, out,
//!    fee). We assert our Rust `ref_compute_swap_step` reproduces every entry.
//!    This validates the reference itself, separate from the guest differential.
//! 2. REFERENCE INVARIANTS: v3 economic invariants on the reference output
//!    (amountIn + feeAmount <= original exact-in amount; amountOut <= requested
//!    exact-out amount; max => next == target; fee monotone in feePips).
//! 3. DIFFERENTIAL via `try_execute`: the FULL branch matrix
//!    {exactIn, exactOut} x {zeroForOne, !zeroForOne} x {max-reached, partial}
//!    x feePips {0, 500, 3000, 10000} x several liquidity/amount magnitudes, plus
//!    random vectors. Witness comes from the trusted reference, so Ok == "guest
//!    agrees with the v3 port" (the commitment binds all 4 outputs + inputs).
//! 4. NEGATIVE soundness: a forged muldiv hint, a forged branch outcome (claiming
//!    `max` when target != next, via a forged sqrtRatioNext commitment), and a
//!    wrong feeAmount commitment are REJECTED, each with the honest counterpart
//!    passing.
//! 5. PROVE+VERIFY: representative steps (release only; debug trips a known
//!    prover-internal SIMD assert — see Phase 1).

use backend::PrimeCharacteristicRing;
use lean_vm::F;
use rand::{RngExt, SeedableRng, rngs::StdRng};
use std::sync::{Mutex, MutexGuard};
use uniswap_v3::{
    SqrtInputs, U256, build_sqrt_witness, build_sqrt_witness_with_bufs, compute_swap_step_inputs,
    emit_sqrt_hints, get_bytecode, prove, ref_compute_swap_step, setup, swap_step_result,
    try_execute, verify,
};

static ARENA_LOCK: Mutex<()> = Mutex::new(());

fn serialize_arena() -> MutexGuard<'static, ()> {
    ARENA_LOCK.lock().unwrap_or_else(|p| p.into_inner())
}

/// Decimal-string U256 (oracle table convenience).
fn u(s: &str) -> U256 {
    U256::from_dec_str(s)
}

/// Run the guest on `inp` and assert it accepts. Witness from the trusted
/// reference, so Ok == "guest agrees with the v3 port".
fn assert_accepts(inp: &SqrtInputs) {
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();
    let (public_input, witness) = build_sqrt_witness(bytecode, inp);
    try_execute(bytecode, &public_input, &witness).unwrap_or_else(|e| panic!("guest must accept {inp:?}: {e:?}"));
}

