#[test]
fn reference_matches_independent_v3_oracle() {
    for (i, (cur, tgt, l, sign, mag, fee, nxt, ai, ao, fa)) in oracle_table().into_iter().enumerate() {
        let r = ref_compute_swap_step(cur, tgt, l, sign, mag, fee);
        assert_eq!(r.sqrt_ratio_next, nxt, "next mismatch at oracle row {i}");
        assert_eq!(r.amount_in, ai, "amountIn mismatch at oracle row {i}");
        assert_eq!(r.amount_out, ao, "amountOut mismatch at oracle row {i}");
        assert_eq!(r.fee_amount, fa, "feeAmount mismatch at oracle row {i}");
    }
}

// ---------------------------------------------------------------------------
// 2. Reference v3 invariants.
// ---------------------------------------------------------------------------

#[test]
fn reference_invariants_hold() {
    for (cur, tgt, l, sign, mag, fee, nxt, _ai, _ao, _fa) in oracle_table() {
        let r = ref_compute_swap_step(cur, tgt, l, sign, mag, fee);
        // max => next == target.
        let max = tgt == r.sqrt_ratio_next;
        if max {
            assert_eq!(r.sqrt_ratio_next, tgt, "max but next != target");
        }
        // committed next matches the table (already checked above; re-assert).
        assert_eq!(r.sqrt_ratio_next, nxt);
        if !sign {
            // exactIn: amountIn + feeAmount <= original input magnitude.
            let (spent, c) = r.amount_in.overflowing_add(r.fee_amount);
            assert!(!c, "amountIn+fee overflowed");
            assert!(spent <= mag, "exactIn: amountIn+fee {spent:?} > magnitude {mag:?}");
        } else {
            // exactOut: amountOut <= requested output magnitude.
            assert!(r.amount_out <= mag, "exactOut: amountOut {:?} > requested {mag:?}", r.amount_out);
        }
    }
}

#[test]
fn reference_fee_monotone_in_fee_pips() {
    // For a fixed exact-in partial swap, feeAmount is non-decreasing in feePips.
    let cur = u("79228162514264337593543950336");
    let tgt = u("71305346262837903834189555302");
    let l = u("1000000000000000000");
    let mag = u("1000000000000000");
    let mut prev = U256::ZERO;
    for fee in [0u32, 100, 500, 1000, 3000, 10000, 50000, 100000] {
        let r = ref_compute_swap_step(cur, tgt, l, false, mag, fee);
        assert!(r.fee_amount >= prev, "fee not monotone at feePips={fee}: {:?} < {prev:?}", r.fee_amount);
        prev = r.fee_amount;
    }
}

// ---------------------------------------------------------------------------
// 3. DIFFERENTIAL over the full branch space, via try_execute.
// ---------------------------------------------------------------------------

/// A sqrt price near 2^96 scaled by `num/den` (kept uint160-valid, nonzero).
fn near_q96(num: u64, den: u64) -> U256 {
    let q96 = U256::Q96;
    // q96 * num / den, via full_mul + simple divmod (den small).
    let prod = q96.full_mul(U256::from_u64(num));
    let (q, _r) = prod.divmod_u256(U256::from_u64(den));
    let v = q.low_u256();
    if v.is_zero() { U256::from_u64(1) } else { v }
}

#[test]
fn differential_full_branch_matrix() {
    let l = u("1000000000000000000"); // 1e18 liquidity
    let small = u("1000000000000000"); // 1e15 -> partial (price barely moves)
    let huge = u("1000000000000000000000000000000"); // 1e30 -> reaches target
    let fees = [0u32, 500, 3000, 10000];
    // Two price pairs: zeroForOne (cur > tgt) and !zeroForOne (cur < tgt).
    let hi = near_q96(1, 1); // 2^96
    let lo = near_q96(9, 10); // 0.9 * 2^96

    for &fee in &fees {
        for amount_sign in [false, true] {
            // {max-reached (huge), partial (small)} x {zfo, !zfo}.
            for &mag in &[small, huge] {
                // zeroForOne: current >= target.
                assert_accepts(&compute_swap_step_inputs(hi, lo, l, amount_sign, mag, fee));
                // !zeroForOne: current < target.
                assert_accepts(&compute_swap_step_inputs(lo, hi, l, amount_sign, mag, fee));
            }
        }
    }
}

#[test]
fn differential_current_equals_target() {
    // current == target: zeroForOne true (>=), and amountIn/out to target are 0,
    // so reach is true (budget >= 0) => next = target, max = true.
    let p = near_q96(1, 1);
    let l = u("1000000000000000000");
    for fee in [0u32, 3000] {
        for sign in [false, true] {
            for mag in [U256::ZERO, u("1000000000000000")] {
                // Phase-5b canonical signed-zero: (sign=1, mag=0) is the rejected
                // non-canonical encoding of int256 0 (the guest asserts
                // amount_sign * (1 - mag_nonzero) == 0). Skip it here; it is
                // exercised as a NEGATIVE test below.
                if sign && mag.is_zero() {
                    continue;
                }
                assert_accepts(&compute_swap_step_inputs(p, p, l, sign, mag, fee));
            }
        }
    }
}

#[test]
fn negative_noncanonical_amount_zero_rejected() {
    // (amount_sign = 1, magnitude = 0) is the non-canonical encoding of int256 0;
    // the Phase-5b carry-in canonical-zero constraint rejects it, while the honest
    // (amount_sign = 0, magnitude = 0) is accepted.
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();
    let p = near_q96(1, 1);
    let l = u("1000000000000000000");

    let ok = compute_swap_step_inputs(p, p, l, false, U256::ZERO, 3000);
    let (pi_ok, w_ok) = build_sqrt_witness(bytecode, &ok);
    try_execute(bytecode, &pi_ok, &w_ok).expect("canonical signed-zero amount must pass");

    // Forge: claim amount_sign = 1 with magnitude 0. Build hints with the forged
    // sign; the guest's canonical-zero assert must reject it.
    let mut bad = ok;
    bad.amount_sign = true;
    let bufs = emit_sqrt_hints(&bad);
    let (pi_bad, w_bad) = build_sqrt_witness_with_bufs(bytecode, &bad, &bufs);
    assert!(
        try_execute(bytecode, &pi_bad, &w_bad).is_err(),
        "non-canonical (sign=1, mag=0) amountRemaining must be rejected"
    );
}

#[test]
fn differential_amount_zero() {
    // amountRemaining == 0 (exactIn, magnitude 0): arlf 0, amountIn-to-target > 0
    // => not reach, getNextFromInput(amount=0) returns current => next=current,
    // max=false, amountIn=0, fee = 0 - 0 = 0.
    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    for fee in [0u32, 500, 3000] {
        assert_accepts(&compute_swap_step_inputs(hi, lo, l, false, U256::ZERO, fee));
        assert_accepts(&compute_swap_step_inputs(lo, hi, l, false, U256::ZERO, fee));
    }
}

#[test]
fn differential_random() {
    let mut rng = StdRng::seed_from_u64(0x05AA_C0DE);
    let l = u("1000000000000000000");
    for _ in 0..40 {
        // random uint160-ish prices near Q96.
        let a = near_q96(1 + rng.random::<u64>() % 1000, 1000);
        let b = near_q96(1 + rng.random::<u64>() % 1000, 1000);
        if a.is_zero() || b.is_zero() || a == b {
            continue;
        }
        let fee = [0u32, 500, 3000, 10000][(rng.random::<u64>() % 4) as usize];
        let sign = rng.random::<u64>() & 1 == 1;
        // magnitude spanning small..huge.
        let exp = rng.random::<u64>() % 31;
        let mag = U256::from_u64(1).shl(exp as u32 * 2);
        // Skip cases that would revert in v3 (reference asserts catch them); only
        // feed non-reverting ones to the guest.
        if std::panic::catch_unwind(|| swap_step_result(&compute_swap_step_inputs(a, b, l, sign, mag, fee))).is_err() {
            continue;
        }
        assert_accepts(&compute_swap_step_inputs(a, b, l, sign, mag, fee));
    }
}

#[test]
fn differential_fee_pips_edges() {
    // feePips at the extremes: 0 and FEE_DENOM-1 (=999999). Both must be accepted;
    // feePips == FEE_DENOM must NOT appear (guest asserts feePips < FEE_DENOM).
    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    let mag = u("1000000000000000");
    for fee in [0u32, 1, 999998, 999999] {
        for sign in [false, true] {
            assert_accepts(&compute_swap_step_inputs(hi, lo, l, sign, mag, fee));
        }
    }
}

// ---------------------------------------------------------------------------
// 4. NEGATIVE soundness (honest counterpart passes; forgery rejected).
// ---------------------------------------------------------------------------

#[test]
fn negative_forged_muldiv_hint_rejected() {
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();

    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    let inp = compute_swap_step_inputs(hi, lo, l, false, u("1000000000000000"), 3000);
    let h = emit_sqrt_hints(&inp);
    let (pi, w) = build_sqrt_witness_with_bufs(bytecode, &inp, &h);
    try_execute(bytecode, &pi, &w).expect("honest swap step must pass");

    // Corrupt the FIRST muldiv_q buffer (the mulDiv for amountRemainingLessFee).
    let mut corrupt = h.clone();
    let qidx = corrupt.iter().position(|hb| hb.label == "muldiv_q").expect("a muldiv_q must exist");
    corrupt[qidx].cells[0] += F::ONE; // perturb one quotient limb
    assert!(
        try_execute(bytecode, &pi, &build_sqrt_witness_with_bufs(bytecode, &inp, &corrupt).1).is_err(),
        "guest must reject a forged muldiv quotient"
    );
}

#[test]
fn negative_forged_max_outcome_rejected() {
    // Forge the committed sqrtRatioNext to `target` (claiming `max` reached) on a
    // PARTIAL step where next != target. Pin the public input to the forged
    // commitment; the guest recomputes the real next (!= target) and commits it,
    // so the digest mismatches -> rejected.
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();

    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    let mag = u("1000000000000000"); // small => partial, next != target
    let inp = compute_swap_step_inputs(hi, lo, l, false, mag, 3000);
    let honest = swap_step_result(&inp);
    assert_ne!(honest.sqrt_ratio_next, lo, "test setup: this step must be partial (next != target)");

    let (pi_ok, w_ok) = build_sqrt_witness(bytecode, &inp);
    try_execute(bytecode, &pi_ok, &w_ok).expect("honest partial step must pass");

    // Build a public input that claims next == target (a different SwapStepResult).
    // We forge by committing a fabricated result via a helper digest: reuse the
    // honest witness but pin PI to a result whose next = target.
    let forged_pi = forged_public_input(&inp, lo, honest.amount_in, honest.amount_out, honest.fee_amount);
    assert!(
        try_execute(bytecode, &forged_pi, &w_ok).is_err(),
        "guest must reject a forged `max` (next=target) commitment on a partial step"
    );
}

#[test]
fn negative_wrong_fee_commitment_rejected() {
    // Pin the public input to a wrong feeAmount; the guest computes the real fee
    // and commits it, so the digest mismatches -> rejected.
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();

    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    let inp = compute_swap_step_inputs(hi, lo, l, false, u("1000000000000000"), 3000);
    let honest = swap_step_result(&inp);
    let (pi_ok, w_ok) = build_sqrt_witness(bytecode, &inp);
    try_execute(bytecode, &pi_ok, &w_ok).expect("honest must pass");

    let wrong_fee = honest.fee_amount.overflowing_add(U256::ONE).0;
    let forged_pi = forged_public_input(&inp, honest.sqrt_ratio_next, honest.amount_in, honest.amount_out, wrong_fee);
    assert!(
        try_execute(bytecode, &forged_pi, &w_ok).is_err(),
        "guest must reject a wrong feeAmount commitment"
    );
}

#[test]
fn negative_fee_pips_at_denom_rejected() {
    // feePips == FEE_DENOM (1_000_000) violates feePips < FEE_DENOM: the guest's
    // 20-bit `(FEE_DENOM-1)-feePips` decomposition fails. We can't go through the
    // reference (it asserts), so build the hint block directly with fee=1_000_000
    // and an arbitrary (honest-shaped) public input — the guest must reject.
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();

    // Honest baseline at a legal fee.
    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    let legal = compute_swap_step_inputs(hi, lo, l, false, u("1000000000000000"), 999999);
    let h_legal = emit_sqrt_hints(&legal);
    let (pi_legal, _) = build_sqrt_witness(bytecode, &legal);
    try_execute(bytecode, &pi_legal, &build_sqrt_witness_with_bufs(bytecode, &legal, &h_legal).1)
        .expect("feePips=999999 must pass");

    // Forge feePips = 1_000_000 in the hint block (everything else identical).
    let mut forged = h_legal.clone();
    let fidx = forged.iter().position(|hb| hb.label == "fee_pips").unwrap();
    forged[fidx].cells = vec![F::from_u32(1_000_000)];
    assert!(
        try_execute(bytecode, &pi_legal, &build_sqrt_witness_with_bufs(bytecode, &legal, &forged).1).is_err(),
        "guest must reject feePips == FEE_DENOM"
    );
}

/// Build a public-input digest committing a FORGED SwapStepResult for `inp` (the
/// inputs stay honest; only the 4 committed outputs are replaced). Mirrors the
/// witness `commit_fold` layout so the digest is well-formed but wrong.
fn forged_public_input(inp: &SqrtInputs, next: U256, ai: U256, ao: U256, fa: U256) -> [F; 8] {
    use backend::poseidon16_compress_pair;
    const HEAD: usize = 16;
    const LIMBS: usize = 32;
    let mut data: Vec<F> = vec![
        F::from_u32(inp.op.code()),
        F::from_u32(inp.flag_a as u32),
        F::from_u32(inp.y_sign as u32),
        F::from_u32(inp.tick_sign as u32),
        F::from_u32(inp.abs_tick),
        F::from_u32(inp.sign_p1 as u32),
        F::from_u32(inp.abs_p1),
        F::from_u32(inp.tick_spacing),
        F::from_u32(inp.bit_pos),
        F::ZERO, // next_val (op 13: 0)
        F::ZERO, // initialized (op 13: 0)
        F::from_u32(inp.fee_pips),
        F::from_u32(inp.amount_sign as u32),
    ];
    for _ in 13..HEAD {
        data.push(F::ZERO);
    }
    data.extend(inp.sqrt_a.to_le_base256_limbs(LIMBS));
    data.extend(inp.sqrt_b.to_le_base256_limbs(LIMBS));
    data.extend(inp.liquidity.to_le_base256_limbs(LIMBS));
    data.extend(inp.amount.to_le_base256_limbs(LIMBS));
    data.extend(next.to_le_base256_limbs(LIMBS)); // result
    data.extend(inp.word.to_le_base256_limbs(LIMBS)); // word
    data.extend(ai.to_le_base256_limbs(LIMBS));
    data.extend(ao.to_le_base256_limbs(LIMBS));
    data.extend(fa.to_le_base256_limbs(LIMBS));
    // left-fold by 8.
    let mut acc: [F; 8] = data[..8].try_into().unwrap();
    let n = data.len() / 8;
    for c in 1..n {
        let chunk: [F; 8] = data[c * 8..(c + 1) * 8].try_into().unwrap();
        acc = poseidon16_compress_pair(&acc, &chunk);
    }
    acc
}

// ---------------------------------------------------------------------------
// 5. PROVE + VERIFY (release only).
// ---------------------------------------------------------------------------

fn prove_verify(inp: &SqrtInputs, label: &str) {
    let _guard = serialize_arena();
    setup();
    let bytecode = get_bytecode();
    let (pi, w) = build_sqrt_witness(bytecode, inp);
    try_execute(bytecode, &pi, &w).unwrap_or_else(|e| panic!("witness gen ({label}) must succeed: {e:?}"));
    let p = prove(bytecode, &pi, &w, 1).unwrap_or_else(|e| panic!("prove ({label}) must succeed: {e:?}"));
    verify(bytecode, &pi, p).unwrap_or_else(|e| panic!("verify ({label}) must succeed: {e:?}"));
}

#[cfg_attr(debug_assertions, ignore = "prover trips a debug-only SIMD assert; run with --release")]
#[test]
fn prove_and_verify_swap_step_exact_in_partial() {
    // exactIn, zeroForOne, PARTIAL (fee taken from remainder).
    let hi = near_q96(1, 1);
    let lo = near_q96(9, 10);
    let l = u("1000000000000000000");
    prove_verify(
        &compute_swap_step_inputs(hi, lo, l, false, u("1000000000000000"), 3000),
        "exactIn/zfo/partial",
    );
}

